mod tests {
    use super::*;

    #[test]
    fn test_golden_vectors() {
        let inp_0 = Input {
            core_temp_c: 350.0,
            coolant_flow: 60.0,
            pressure_bar: 130.0,
            flux_rate: 0.75,
        };
        let out_0 = infer(&inp_0);
        assert_eq!(out_0.regime_id, 9);
        assert!((out_0.logit_normal - -6.2029781478635799).abs() < 1e-9);
        assert!((out_0.logit_throttle - 7.8190961857216728).abs() < 1e-9);
        assert!((out_0.logit_scram - 1.3099735109037134).abs() < 1e-9);
        let _ = out_0.class_id.as_usize();
        let inp_1 = Input {
            core_temp_c: 284.58527243924976,
            coolant_flow: 48.597592259150971,
            pressure_bar: 148.21878604841328,
            flux_rate: 0.10035872659331853,
